insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_art2_v1'
from (values
('117.303.c.1.A',3,'A student draws a seashell next to a photo of the same shell and notes how the spiral differs. This is an example of what?','["Using visual comparison to illustrate an idea", "Copying a classmate", "Ignoring the subject", "Choosing paint at random"]'::jsonb,0,'Comparing two visual sources clarifies ideas.','original'),
('117.303.c.1.A',3,'Placing a sketch of a crumpled paper bag beside a smooth ceramic bowl helps show which concept?','["The rule of thirds", "Contrast in texture", "Perfect symmetry", "Linear perspective"]'::jsonb,1,'Side by side comparisons reveal contrast.','original'),
('117.303.c.1.B',3,'A designer uses thick and thin diagonal strokes to suggest movement across a page. Which element of art is most active?','["Space only", "Value only", "Line", "Form only"]'::jsonb,2,'Varied lines create movement.','original'),
('117.303.c.1.B',3,'Adding gradual shading to a flat circle makes it look like a sphere. Which elements of art are being applied?','["Emphasis and contrast", "Pattern and rhythm", "Balance and unity", "Value and form"]'::jsonb,3,'Shading builds three-dimensional form.','original'),
('117.303.c.1.C',3,'A poster has one large, bright red shape on a field of small gray shapes so the eye goes there first. Which principle is applied?','["Emphasis", "Rhythm only", "Repetition", "Proportion only"]'::jsonb,0,'A dominant element creates emphasis.','original'),
('117.303.c.1.C',3,'A painter arranges two equal trees on each side of a road so the picture feels stable. Which principle is used?','["Contrast of color only", "Balance, specifically symmetry", "Variety", "Movement"]'::jsonb,1,'Matching sides create symmetrical balance.','original'),
('117.303.c.1.D',3,'Watercolor is often chosen for soft, flowing skies. This shows that artists consider what?','["The studio floor", "The brush color", "How well a medium suits the idea being expressed", "The cheapest tool always"]'::jsonb,2,'Media should match the expressive goal.','original'),
('117.303.c.1.D',3,'A sculptor wants to express strength and permanence. Which medium might be most suitable?','["Thin thread", "Tissue paper", "Soap bubbles", "Carved stone"]'::jsonb,3,'Stone suggests durability.','original'),
('117.303.c.2.A',3,'For a still life, a student draws the arrangement three ways: from above, from the side and up close. What is she doing?','["Creating multiple solutions from direct observation", "Copying a poster", "Using only one idea", "Skipping planning"]'::jsonb,0,'Several views provide multiple solutions.','original'),
('117.303.c.2.A',3,'Why is it helpful to develop more than one solution for an art problem?','["It wastes supplies", "It lets the artist choose the strongest idea", "It avoids decisions", "It ends the project"]'::jsonb,1,'Exploring options improves results.','original'),
('117.303.c.2.B',3,'A student designs a clear symbol for a school recycling bin so everyone understands it. This is a practical application of what?','["Weaving", "Photography", "Design skills", "Pottery wheel use"]'::jsonb,2,'Design makes ideas clear and practical.','original'),
('117.303.c.2.B',3,'Which task is an example of applying design to clarify a presentation?','["Using tiny crowded text", "Adding random clip art", "Using a very bright background with pale text", "Choosing a readable font and clear layout for a slide"]'::jsonb,3,'Good layout improves clarity.','original'),
('117.303.c.2.C',3,'A student remixes a famous painting into a new composition, changing the subject and style. What should she consider about the source?','["Whether the source is protected by copyright or in the public domain", "Whether it is old by weight", "Whether it is large", "Only whether it is popular"]'::jsonb,0,'Appropriation depends on legal status.','original'),
('117.303.c.2.C',3,'Which of these best describes fair, ethical use of a source image?','["Selling it unchanged", "Transforming it so the new work is original and giving credit", "Claiming it as your own", "Copying it exactly and signing it"]'::jsonb,1,'Transformation and credit are ethical practices.','original'),
('117.303.c.2.D',3,'An artist makes a collage of torn blue paper to show loneliness. This is an example of what?','["Tracing a map", "Copying a logo", "Communicating a feeling through original artwork", "Following a tutorial exactly"]'::jsonb,2,'Original art expresses personal ideas.','original'),
('117.303.c.2.D',3,'Which piece best communicates an impression of a busy city?','["A blank sheet", "A random smudge only", "A single dot", "A layered painting of overlapping buildings and bright lights"]'::jsonb,3,'Layered, active images suggest a busy place.','original'),
('117.303.c.2.E',3,'Two students plan a diptych in which each paints one panel that answers the other. What skill is most needed?','["Collaboration and agreement on shared ideas", "Painting over each other", "Ignoring the theme", "Working in secret"]'::jsonb,0,'Collaboration needs shared planning.','original'),
('117.303.c.2.E',3,'When a team creates a sculpture, who decides on the design?','["The teacher alone with no input", "The team, through discussion and compromise", "No one", "Only the loudest member"]'::jsonb,1,'Collaborative design is a group decision.','original'),
('117.303.c.2.F',3,'Which medium is best for a student who wants to print multiple copies of an image?','["Pencil sketch", "Single clay pinch pot", "Linocut or another printmaking process", "Watercolor wash"]'::jsonb,2,'Printmaking produces editions.','original'),
('117.303.c.2.F',3,'A student chooses charcoal to create deep, dramatic shadows. This shows what?','["Following no rules", "Avoiding planning", "Random choice", "Selecting a medium to communicate a specific idea"]'::jsonb,3,'Medium choice supports the idea.','original'),
('117.303.c.3.A',3,'A student studies Impressionism and notes that artists painted outdoors to capture changing light. This is an example of what?','["Identifying a theme and trend in a historical style", "Memorizing prices", "Studying unrelated music", "Copying one painting"]'::jsonb,0,'Styles share themes and trends.','original'),
('117.303.c.3.A',3,'Comparing Baroque and Modernist art, a student looks for differences in what?','["Museum hours", "Subject matter, technique and the ideas they express", "Frame colors only", "Painter''s height"]'::jsonb,1,'Comparison focuses on style and meaning.','original'),
('117.303.c.3.B',3,'A student studies how Maori carving uses spirals and patterns to tell family stories. She is analyzing what?','["A modern advertisement", "A random doodle", "Specific characteristics of artwork from a culture", "A weather map"]'::jsonb,2,'Cultural analysis looks at symbols and techniques.','original'),
('117.303.c.3.B',3,'Which feature might you analyze when comparing art from different cultures?','["The price of the frame", "The size of the signature", "The distance from home", "Materials, symbols and purpose of the work"]'::jsonb,3,'Materials and symbols reflect culture.','original'),
('117.303.c.3.C',3,'A class works with a city to paint a mural at a bus stop. What do they need to consider?','["The community''s needs, safety and permission", "Painting over other work", "Only personal taste", "Ignoring the neighbors"]'::jsonb,0,'Community art needs buy-in.','original'),
('117.303.c.3.C',3,'Community-based art can help a neighborhood by doing what?','["Hiding local history", "Expressing shared identity and improving public space", "Removing all art", "Raising noise levels"]'::jsonb,1,'Public art builds identity.','original'),
('117.303.c.3.D',3,'A student researches how an illustrator starts a freelance business. This is an example of exploring what?','["Medical careers", "Only hobbies", "Entrepreneurial opportunities in art", "School sports"]'::jsonb,2,'Freelancing is an entrepreneurial path.','original'),
('117.303.c.3.D',3,'Which job requires strong art and design skills?','["Electrician only", "Accountant only", "Truck dispatcher only", "Animator"]'::jsonb,3,'Animation is an art career.','original'),
('117.303.c.4.A',3,'During a class discussion, a student justifies her choice of a cool palette by saying it creates a calm mood. She is doing what?','["Interpreting and justifying artistic decisions", "Insulting a peer", "Skipping reflection", "Avoiding the question"]'::jsonb,0,'Justification links choices to intent.','original'),
('117.303.c.4.A',3,'Which kind of feedback best helps an artist improve?','["Silent looks", "Specific comments tied to what is visible in the work", "Personal attacks", "Vague praise"]'::jsonb,1,'Specific feedback guides revision.','original'),
('117.303.c.4.B',3,'In a critique, a student explains how the artist arranged shapes and then says what the work might mean. Which steps is she using?','["Only judging", "Only measuring", "Analysis and interpretation", "Only describing"]'::jsonb,2,'These are middle steps in a critique.','original'),
('117.303.c.4.B',3,'Which question belongs in the evaluation step of a critique?','["How big is the canvas?", "Who owns it?", "What colors do I see?", "How successful is the work in communicating its idea?"]'::jsonb,3,'Evaluation judges effectiveness.','original'),
('117.303.c.4.C',3,'After a critique says her composition feels crowded, a student simplifies the background. She is doing what?','["Using responses to critique to make decisions about her work", "Quitting the project", "Copying another student", "Ignoring feedback"]'::jsonb,0,'Critique guides revisions.','original'),
('117.303.c.4.C',3,'Why is it useful to keep notes from critiques?','["They replace artwork", "They help plan future directions for personal work", "They lower grades", "They prevent revision"]'::jsonb,1,'Notes track growth.','original'),
('117.303.c.4.D',3,'A portfolio shows sketches, final pieces and a short reflection on each. This helps a viewer see what?','["Only prices", "Only finished work", "The artist''s growth and thinking over time", "Only the artist''s name"]'::jsonb,2,'Portfolios show process and progress.','original'),
('117.303.c.4.D',3,'A student photographs her sculptures to make an electronic portfolio. What is one advantage?','["It lowers quality always", "It prevents feedback", "It deletes the originals", "It makes the work easy to share and update"]'::jsonb,3,'Digital portfolios are shareable.','original'),
('117.303.c.4.E',3,'A student visits an exhibit and writes about how the curator groups the works. She is analyzing what?','["How an exhibition communicates ideas", "Parking rules", "Ticket prices", "The gift shop"]'::jsonb,0,'Exhibition analysis considers arrangement and theme.','original'),
('117.303.c.4.E',3,'Which is the best basis for a precise conclusion about an artist''s body of work?','["One quick glance", "Details from several works, such as subjects, techniques and themes", "The title alone", "A friend''s guess"]'::jsonb,1,'Evidence from multiple works supports conclusions.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
